import { converter } from "./x2t";
import { MockSocket } from "./socket";
import {
  User,
  Participant,
  AscSaveTypes,
  ServerOptions,
  DocEditor,
  AvsFileType,
} from "./types";
import { emptyDocx, emptyPdf, emptyPptx, emptyXlsx } from "./empty";
import { getDocumentType, getFileExt } from "./utils";
import { convertLegacyBuffer } from "./doc-convert";
import { allPlugins, featuredPlugins, getPluginConfigUrl } from "./plugins";
import { isVOSMode } from "@/utils/vos/fastpath";
import {
  saveStoredFile,
  saveSharedDocument,
  clientLog,
  type SharedTarget,
} from "@/utils/vos/storage";

function mergeBuffers(buffers: Uint8Array[]) {
  const totalLength = buffers.reduce((acc, buffer) => acc + buffer.length, 0);
  const mergedBuffer = new Uint8Array(totalLength);
  let offset = 0;
  for (const buffer of buffers) {
    mergedBuffer.set(buffer, offset);
    offset += buffer.length;
  }
  return mergedBuffer;
}

function randomId() {
  return Math.random().toString(36).substring(2, 9);
}

function getUrl(data: Uint8Array, type?: string) {
  const blob = new Blob([data as Uint8Array<ArrayBuffer>], {
    type: type || "application/octet-stream",
  });
  return URL.createObjectURL(blob);
}

export class EditorServer {
  private id = "";
  private socket: MockSocket | null = null;
  private sessionId: string = "session-id";
  private user: User = {
    id: "uid",
    name: "Me",
  };
  private client = {
    buildVersion: "9.3.0",
    buildNumber: 8,
  };
  private participants: Participant[] = [];
  private syncChangesIndex = 0;
  private loadPromise: Promise<void> | null = null;

  private fileType: string = "docx";
  private title: string = "";
  private isNewDocument = false;
  /**
   * 打开文档时的原始字节与文件名（未经 x2t 转换）。
   *
   * Collabora 是服务端渲染，只能通过 WOPI 从 storage 取文件，因此本地打开的
   * 文档要先原样推一份到存储。fsMap 里只有转换后的 Editor.bin，回写不出可用
   * 的原文件，所以这里必须单独留底。
   */
  private originalData: ArrayBuffer | null = null;
  private originalName = "";
  /**
   * 打开共享源（平台授权目录 / NAS）里的文档时记录的保存落点。
   *
   * 非空表示"编辑的是共享盘上的原文件"：保存直接写回该路径，而不是写进
   * 用户私有目录（Collabora 会话同样按它走 WOPI 直接编辑原文件）。
   */
  private sharedTarget: SharedTarget | null = null;
  /** 私有文档的版本凭据：打开时拿到，保存时回传，防止别处改过之后被整份覆盖 */
  private privateTarget: { token: string } | null = null;
  /** 新建文档在编辑期间静默保存用的默认文件名（退出时 UI 据此弹框改名） */
  private untitledSavedAs: string | null = null;
  private requestFileName:
    | ((suggestedName: string, extension: string) => Promise<string | null>)
    | null = null;
  private saveRequest:
    | {
        resolve: (success: boolean) => void;
        timer: ReturnType<typeof setTimeout>;
      }
    | null = null;
  private fsMap: Map<string, Uint8Array> = new Map();
  private urlsMap: Map<string, string> = new Map();

  private downloadId: string = "";
  private downloadParts: Uint8Array[] = [];

  /** 导出模式：非空表示当前 downloadAs 会话用于导出字节（上传知识库） */
  private exportResolver:
    | ((result: { fileName: string; data: Uint8Array } | null) => void)
    | null = null;
  private exportFileName: string | null = null;

  private options: ServerOptions = {};

  constructor(options: ServerOptions = {}) {
    this.options = options;
    this.send = this.send.bind(this);
    this.handleConnect = this.handleConnect.bind(this);
    this.handleMessage = this.handleMessage.bind(this);
  }

  async open(
    file: File,
    {
      fileType,
      fileName,
      sharedTarget,
      privateToken,
    }: {
      fileType?: string;
      fileName?: string;
      /** 共享源文档：保存时写回该路径（编辑原文档） */
      sharedTarget?: SharedTarget | null;
      /** 私有文档：打开时拿到的版本凭据，保存时回传做一次 CAS */
      privateToken?: string;
    } = {},
  ) {
    const title = fileName || file.name;
    this.fileType = fileType || getFileExt(file.name) || "docx";
    const documentType = getDocumentType(this.fileType);
    this.id = randomId();
    this.title = title;
    this.isNewDocument = false;
    this.sharedTarget = sharedTarget ?? null;
    this.privateTarget = privateToken ? { token: privateToken } : null;
    const buffer = await file.arrayBuffer();
    this.originalData = buffer;
    this.originalName = title;
    this.loadPromise = this.loadDocument(buffer, this.fileType);

    return {
      id: this.id,
      documentType,
    };
  }

  openNew(fileType?: string) {
    this.fileType = fileType || "docx";
    // TODO: should generate new id?
    this.id = this.id || randomId();
    this.title = "New Document";
    this.isNewDocument = true;
    this.originalData = null;
    this.originalName = "";
    this.sharedTarget = null;
    const documentType = getDocumentType(this.fileType);

    let binData: Uint8Array | null = null;

    switch (documentType) {
      case "word":
        binData = Uint8Array.from(emptyDocx, (v) => v.charCodeAt(0));
        break;
      case "cell":
        binData = Uint8Array.from(emptyXlsx, (v) => v.charCodeAt(0));
        break;
      case "slide":
        binData = Uint8Array.from(emptyPptx, (v) => v.charCodeAt(0));
        break;
      case "pdf":
        binData = Uint8Array.from(emptyPdf, (v) => v.charCodeAt(0));
        break;
    }

    if (!binData) {
      throw new Error("Failed to create new document");
    }

    this.fsMap.set("Editor.bin", binData);
    this.urlsMap.set("Editor.bin", getUrl(binData));

    return {
      id: this.id,
      documentType: documentType,
    };
  }

  async openUrl(
    url: string,
    {
      fileType,
      fileName,
      loader = (url: string) => fetch(url).then((res) => res.arrayBuffer()),
    }: {
      fileType?: string;
      fileName?: string;
      loader?: (url: string) => Promise<ArrayBuffer>;
    } = {},
  ) {
    const title = fileName || decodeURIComponent(url.split("/").pop() || "Document")
    this.fileType = fileType || getFileExt(title) || "docx";
    const documentType = getDocumentType(this.fileType);
    this.id = randomId();
    this.title = title;
    this.isNewDocument = false;
    this.sharedTarget = null;
    // 清掉上一个文档的留底：openUrl 是惰性下载，字节要等装载时才拿得到，
    // 不重置的话会残留上一份文件的字节（PDF 保存回退时会拿错文件）。
    this.originalData = null;
    this.originalName = "";
    this.loadPromise = this.loadDocument(() => loader(url), this.fileType);

    return {
      id: this.id,
      documentType,
    };
  }

  getDocument() {
    if (!this.id) {
      this.openNew();
    }

    return {
      fileType: this.fileType,
      key: this.id,
      title: this.title,
      url: "/" + this.id,
    };
  }

  getUser() {
    return this.user;
  }

  /** 当前装载的是否是"新建文档"（新建文档不进存储，不能走 Collabora）。 */
  isNewDocumentOpen() {
    return this.isNewDocument;
  }

  /**
   * `open(file)` 打开时留底的原文件。
   *
   * 只对"有 File 对象"的入口（拖拽 / 选择本地文件 / 我的文档下载后打开）
   * 有值；`openUrl` 是惰性下载，决策时通常还没有字节，返回 null。
   */
  getOriginalDocument(): { name: string; data: ArrayBuffer } | null {
    if (!this.originalData || !this.originalName) return null;
    return { name: this.originalName, data: this.originalData };
  }

  /**
   * 等当前文档装载完成（惰性下载 + x2t 转换）。
   *
   * 换 Collabora 会话前必须等它：原文件字节是装载时才留底的，不等的话
   * `getOriginalDocument()` 还是 null，「模板 / 外链」这类文档就换不到会话。
   */
  async ensureLoaded(): Promise<void> {
    if (this.loadPromise) await this.loadPromise;
  }

  /**
   * 当前文档的共享源落点（非空表示编辑的是共享盘上的原文件）。
   *
   * 编辑器页据此决定 Collabora 会话参数：共享源文档不再往私有存储推副本，
   * 而是让 Collabora 通过 WOPI 直接读写原文件。
   */
  getSharedTarget(): SharedTarget | null {
    return this.sharedTarget;
  }

  private async loadDocument(
    buffer: ArrayBuffer | (() => Promise<ArrayBuffer>),
    fileType: string,
  ) {
    let data: ArrayBuffer =
      typeof buffer == "function" ? await buffer() : buffer;

    // 留底原文件字节。Collabora 是服务端渲染，只能通过 WOPI 从 storage 取文件，
    // 而 fsMap 里只有 x2t 转换后的 Editor.bin（回写不出可用的原文件）。
    //
    // 必须在**转换之前**留：一来 .doc 转换后字节就变成 docx 了，而 Collabora
    // 是按原格式读写；二来 openUrl（模板 / 外链）是惰性下载，字节要到这里才拿
    // 得到——之前只有 pdf 分支留了底，于是模板这类"只给了 URL"的文档永远换不到
    // Collabora 会话（点了「使用 Collabora 打开」只会回退 OnlyOffice）。
    this.originalData = data;
    this.originalName = this.originalName || this.title;

    let output: Uint8Array | null = null;
    let media: { [key: string]: Uint8Array } = {};

    if (fileType == "pdf") {
      // PDF 不走 x2t：内核直接拿原始字节渲染（上面已经留底了那一份）。保存时若
      // 导出没产出真 PDF，就把留底的那份写回去——保证写进去的一定是这份文件自己
      // 的内容，不会串到别的文档。
      output = new Uint8Array(data);
    } else {
      // 老版 .doc：x2t 直接解析排版会错乱，先用 LibreOffice 转成 docx 副本
      // （原文件不动，仅本次打开的内存数据），再按 docx 正常解析渲染。
      // 老 ppt / xls 不在这里处理——它们默认由 Collabora 原生读写。
      if (fileType == "doc") {
        data = await convertLegacyBuffer(data, "doc", "docx");
      }
      // docx 页眉/页脚浮动元素修复已按反馈整体移除，文档按原生内容交给内核解析。
      const result = await converter.convert({
        data: data,
        // .doc 的字节此时已是 docx，按真实格式喂给 x2t
        fileFrom: "doc." + (fileType == "doc" ? "docx" : fileType),
        fileTo: "Editor.bin",
      });
      output = result.output;
      media = result.media;
    }

    if (!output) {
      throw new Error("Failed to convert file");
    }

    if (this.urlsMap.size > 0) {
      this.urlsMap.forEach((url) => URL.revokeObjectURL(url));
    }
    this.fsMap.set("Editor.bin", output);
    this.urlsMap.set("Editor.bin", getUrl(output));
    for (const name in media) {
      this.addMedia(name, media[name]);
    }
  }

  private addMedia(name: string, data: Uint8Array) {
    const pathname = "media/" + name;
    const url = getUrl(data);
    this.fsMap.set(pathname, data);
    this.urlsMap.set(pathname, url);
    return url;
  }

  setClient(info: Partial<typeof this.client>) {
    this.client = {
      ...this.client,
      ...info,
    };
  }

  setFileNameRequester(
    requester:
      | ((suggestedName: string, extension: string) => Promise<string | null>)
      | null,
  ) {
    this.requestFileName = requester;
  }

  /**
   * 新建文档已用默认名静默保存的文件名（如 "New Document.docx"）。
   * 非新建文档、或尚未保存过时返回 null —— UI 在退出文档时据此弹框
   * 让用户确认正式命名。
   */
  getUntitledSaveName(): string | null {
    return this.isNewDocument ? this.untitledSavedAs : null;
  }

  /** 退出弹框命名（或用户确认保留默认名）后清除标记，避免再次弹出 */
  markUntitledNamed(): void {
    this.isNewDocument = false;
    this.untitledSavedAs = null;
  }

  requestSave(editor: DocEditor): Promise<boolean> {
    if (this.saveRequest || this.exportResolver) {
      return Promise.resolve(false);
    }
    return new Promise<boolean>((resolve) => {
      const timer = setTimeout(() => {
        if (!this.saveRequest) return;
        this.saveRequest = null;
        resolve(false);
      }, 60_000);
      this.saveRequest = { resolve, timer };
      try {
        editor.downloadAs({ extension: this.fileType, isDownload: false });
      } catch (error) {
        console.error("Failed to request document save", error);
        this.finishSaveRequest(false);
      }
    });
  }

  /** 导出当前文档字节（供「上传到知识库」复用），失败或超时返回 null */
  exportDocument(
    editor: DocEditor,
    fileName: string,
  ): Promise<{ fileName: string; data: Uint8Array } | null> {
    if (!editor || this.saveRequest || this.exportResolver) {
      return Promise.resolve(null);
    }
    return new Promise((resolve) => {
      const timer = setTimeout(() => {
        this.exportResolver = null;
        this.exportFileName = null;
        console.error("Document export timed out");
        resolve(null);
      }, 60_000);
      this.exportResolver = (result) => {
        clearTimeout(timer);
        this.exportResolver = null;
        this.exportFileName = null;
        resolve(result);
      };
      const originalFileName = this.exportFileName;
      this.exportFileName = fileName;
      try {
        editor.downloadAs({ extension: this.fileType, isDownload: false });
      } catch (error) {
        console.error("Failed to request document export", error);
        this.exportFileName = originalFileName;
        this.exportResolver(null);
      }
    });
  }

  private finishSaveRequest(success: boolean) {
    if (!this.saveRequest) return;
    const { resolve, timer } = this.saveRequest;
    this.saveRequest = null;
    clearTimeout(timer);
    resolve(success);
  }

  handleConnect({ socket }: { socket: MockSocket }) {
    this.socket = socket;
    const { send, sessionId, client } = this;

    this.participants = [
      {
        connectionId: this.sessionId,
        encrypted: false,
        id: this.user.id,
        idOriginal: this.user.id,
        indexUser: 1,
        isCloseCoAuthoring: false,
        isLiveViewer: false,
        username: this.user.name,
        view: false,
      },
    ];

    socket.server.on("message", this.handleMessage);

    send({
      maxPayload: 100000000,
      pingInterval: 25000,
      pingTimeout: 20000,
      sid: sessionId,
      upgrades: [],
    });

    send({
      type: "license",
      license: {
        type: 3,
        buildNumber: client.buildNumber,
        buildVersion: client.buildVersion,
        light: false,
        mode: 0,
        rights: 1,
        protectionSupport: true,
        isAnonymousSupport: true,
        liveViewerSupport: true,
        branding: false,
        customization: true,
        advancedApi: false,
      },
    });
  }

  handleDisconnect() {
    this.socket = null;
  }

  send(...msg: unknown[]) {
    if (!this.socket) {
      console.error("Socket is not connected");
      return;
    }
    this.socket.server.emit("message", ...msg);
  }

  async handleMessage(msg: Record<string, string>) {
    const { send, sessionId, participants, user, client } = this;
    const type =
      typeof msg === "object" && msg && "type" in msg ? msg.type : null;
    switch (type) {
      case "auth":
        const changes: unknown[] = [];
        send({
          type: "authChanges",
          changes: changes,
        });
        send({
          type: "auth",
          result: 1,
          sessionId: sessionId,
          participants: participants,
          locks: [],
          //   changes: changes,
          //   changesIndex: 0,
          indexUser: 1,
          buildVersion: client.buildVersion || "9.3.0",
          buildNumber: client.buildNumber || 9,
          licenseType: 3,
          editorType: 2,
          mode: "edit",
          permissions: {
            comment: true,
            chat: true,
            download: true,
            edit: true,
            fillForms: false,
            modifyFilter: true,
            protect: true,
            print: true,
            review: false,
            copy: true,
          },
        });

        try {
          if (this.loadPromise) {
            await this.loadPromise;
          }
          send({
            type: "documentOpen",
            data: {
              type: "open",
              status: "ok",
              data: {
                ...Object.fromEntries(this.urlsMap),
              },
            },
          });
        } catch (err) {
          console.error(err);
          // TODO: send error message
          send({
            type: "documentOpen",
            data: {
              type: "open",
              status: "ok",
              data: {
                "Editor.bin": "",
              },
            },
          });
        }
        break;
      case "isSaveLock":
        send({
          type: "saveLock",
          saveLock: false,
        });
        break;
      case "saveChanges":
        send({
          type: "unSaveLock",
          index: -1,
          syncChangesIndex: ++this.syncChangesIndex,
          time: +new Date(),
        });
        break;
      case "getLock":
        send({
          type: "getLock",
          locks: {
            [msg.block]: {
              time: +new Date(),
              user: user?.id,
              block: msg.block,
            },
          },
        });
        send({
          type: "releaseLock",
          locks: {
            [msg.block]: {
              time: +new Date(),
              user: user?.id,
              block: msg.block,
            },
          },
        });
        break;
    }
  }

  async handleRequest(req: Request) {
    const u = new URL(req.url);

    const { id: key, send } = this;

    if (u.pathname.endsWith("/downloadas/" + key)) {
      const cmd = JSON.parse(u.searchParams.get("cmd") || "{}");
      const buffer = await req.arrayBuffer();

      let formatTo = cmd.outputformat;
      if (!formatTo && this.fileType === "pdf") {
        formatTo = 513;
      }

      // x2t 无法把内部 bin 导出为老版 .doc 二进制格式（输出 0 字节文件，
      // PUT 到存储后被判 empty body 返回 400 → 编辑器弹「保存文件时发生错误」）。
      // 所以老 .doc 保存分两步：先让 x2t 导出 docx，再用 LibreOffice 转回 .doc
      // （见下方 round-trip）——格式、文件名都保持原样，用户无感知。
      // 老 ppt / xls 不在这里处理——它们默认由 Collabora 原生读写、按原格式保存。
      const saveExt = (getFileExt(cmd.title) || this.fileType || "docx").toLowerCase();
      const isLegacyDoc = saveExt === "doc";
      if (isLegacyDoc) {
        formatTo = AvsFileType.AVS_FILE_DOCUMENT_DOCX;
      }

      const browserDownload = (data: Uint8Array) => {
        const blob = new Blob([new Uint8Array(data)]);
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = cmd.title || "test.docx";
        a.click();
        URL.revokeObjectURL(url);
      };

      const download = async () => {
        const vosMode = await isVOSMode();
        const exporting = this.exportResolver !== null && this.exportFileName !== null;
        let saveName = exporting
          ? this.exportFileName!
          : this.title || cmd.title || `document.${this.fileType}`;
        if (vosMode && this.isNewDocument && !exporting) {
          // 新建文档在编辑期间（自动/手动保存）一律用默认名静默保存，
          // 不打断用户；退出文档时才由 UI 弹框确认命名（对齐 WPS 等
          // 主流办公软件习惯），见 page.tsx 的 closeDocument。
          if (!/\.[a-z0-9]{2,5}$/i.test(saveName)) {
            saveName += `.${this.fileType}`;
          }
          this.untitledSavedAs = saveName;
        }

        const input = mergeBuffers(this.downloadParts);
        let fileFrom = "from.bin";
        if (cmd.format == "pdf") {
          fileFrom = "from.pdf";
        }

        const fileTo = "doc." + (isLegacyDoc ? "docx" : saveExt);

        let { output } = await converter.convert({
          data: input.buffer,
          fileFrom: fileFrom,
          fileTo: fileTo,
          formatTo: formatTo,
          media: Object.fromEntries(this.fsMap),
        });
        // PDF 特例：内核交付的分片是它自己的内部容器（docx 结构 zip）。如果导出
        // 没真的产出 PDF，就**存原始 PDF 字节**——这样本地上传的 PDF 会以一份
        // 有效 PDF 落进「我的文档」（和以前一样能看见、能打开），从我的文档打开的
        // PDF 则保持原样。绝不把内部容器写成 .pdf（那会让文件打不开）。
        // 本次编辑（批注等）暂不落盘，等导出那条路打通。
        if (this.fileType === "pdf" || cmd.format == "pdf") {
          const looksLikePdf =
            !!output &&
            output.byteLength > 4 &&
            output[0] === 0x25 &&
            output[1] === 0x50 &&
            output[2] === 0x44 &&
            output[3] === 0x46;
          if (!looksLikePdf) {
            const original = this.originalData;
            if (original && original.byteLength > 0) {
              output = new Uint8Array(original);
              clientLog(
                `save-note: ${saveName} :: pdf export produced no PDF, saved the original bytes`,
              );
            } else {
              // 没有原始字节可回退（例如从共享盘打开）：交给服务端按"保持原文件
              // 不动 + 回成功"处理，不报错、也不写出坏文件。
              clientLog(
                `save-note: ${saveName} :: pdf export produced no PDF and no original bytes`,
              );
            }
          }
        }
        if (!output || output.byteLength === 0) {
          const isPdf = this.fileType === "pdf" || cmd.format == "pdf";
          if (!isPdf) {
            // 非 PDF：x2t 没产出时沿用编辑器交付的分片（分片本身就是一份完整
            // OOXML 文档，Word/Excel 正常打开）。"空输出即失败"的分支在更早版本
            // 就存在，这里额外补一层兜底，让非 PDF 的保存不会因转换没产出而失败。
            output = input;
            clientLog(
              `save-note: ${saveName} :: conversion returned nothing, saved the editor bytes`,
            );
          }
        }
        if (!output || output.byteLength === 0) {
          // 0 字节输出也视为失败：空文件 PUT 到存储会被判 empty body（400）
          console.error("Conversion failed (empty output)");
          clientLog(`save-failed: ${saveName} :: conversion produced empty output`);
          return { status: "error" };
        }
        // 老 .doc：编辑器只能导出 docx（x2t 写不了 .doc 二进制），
        // 经 LibreOffice 转回 .doc —— 格式、文件名都保持原样，用户无感知
        let finalOutput = output;
        if (isLegacyDoc) {
          try {
            finalOutput = new Uint8Array(
              await convertLegacyBuffer(finalOutput, "docx", "doc"),
            );
          } catch (error) {
            clientLog(`save-failed: ${saveName} :: doc round-trip failed :: ${error}`);
            console.error("Failed to convert docx back to legacy .doc", error);
            return { status: "error" };
          }
        }

        // 导出模式（上传知识库）：把转换后的字节回调出去，不落 VOS 存储、
        // 不做浏览器下载。
        if (exporting && this.exportResolver) {
          const resolver = this.exportResolver;
          this.exportResolver = null;
          const exportedName = this.exportFileName || saveName;
          this.exportFileName = null;
          resolver({ fileName: exportedName, data: finalOutput });
          return { status: "ok" };
        }

        // 共享源文档（平台授权目录 / NAS）：保存写回原路径，即"编辑共享盘上的
        // 原文件"。写入失败（目录只读、权限不足）保持错误状态，不改走浏览器
        // 下载，否则用户会误以为已经存回原文件。
        if (vosMode && this.sharedTarget) {
          const shared = this.sharedTarget;
          clientLog(
            `shared-save-begin: ${shared.source}:${shared.path}` +
              ` (${finalOutput.byteLength} bytes, token=${shared.token || "-"})`,
          );
          try {
            const nextToken = await saveSharedDocument(
              shared.source,
              shared.path,
              finalOutput,
              shared.token || "",
            );
            // 更新手里的凭据：不更新的话，下一次自动保存会被**我们自己**刚写进去
            // 的那一版挡住（凭据还停留在上一版）。
            if (nextToken) {
              this.sharedTarget = { ...shared, token: nextToken };
            }
            clientLog(`shared-save-ok: ${shared.path} (token=${nextToken || "-"})`);
            return { status: "ok" };
          } catch (error) {
            // 版本冲突：盘上那份在我们打开之后被别人改过了。这里**绝不**自动改用
            // 对方的新版本号重试——那等于把对方刚写进去的内容抹掉。保持错误状态，
            // 让用户自己决定（另存到「我的文档」或重新打开）。
            const reason =
              error instanceof Error && error.message === "SHARED_VERSION_CHANGED"
                ? "version-changed"
                : String(error);
            clientLog(`shared-save-failed: ${shared.path} :: ${reason}`);
            console.error("Failed to save document back to shared source", error);
            return { status: "error" };
          }
        }

        // VOS deployment: persist directly into the private app storage.
        // A failed server save must remain an error instead of silently changing
        // the operation into a browser download.
        if (vosMode) {
          const target = this.privateTarget;
          clientLog(
            `save-begin: ${saveName} (${finalOutput.byteLength} bytes, token=${target?.token || "-"})`,
          );
          try {
            const nextToken = await saveStoredFile(
              saveName,
              finalOutput,
              target?.token || "",
            );
            // 更新手里的凭据：不更新的话，下一次自动保存会被我们自己刚写进去的那一版挡住
            if (target && nextToken) {
              this.privateTarget = { ...target, token: nextToken };
            }
            clientLog(`save-ok: ${saveName} (token=${nextToken || "-"})`);
            return { status: "ok" };
          } catch (error) {
            // 版本冲突：这份私有文档在我们打开之后被别处改过了（同一个账号的另一个
            // 窗口/设备）。绝不能自动重试覆盖——那会把对方的改动整份抹掉。保持错误
            // 状态，让用户自己决定（另存 / 重新打开）。
            const reason =
              error instanceof Error && error.message === "VERSION_CHANGED"
                ? "version-changed"
                : String(error);
            clientLog(`save-failed: ${saveName} :: ${reason}`);
            console.error("Failed to save document to VOS storage", error);
            return { status: "error" };
          }
        }

        clientLog("save-skipped: not vos mode");
        browserDownload(finalOutput);
        return { status: "ok" };
      };

      let result = {
        status: "ok",
      };

      switch (cmd.savetype) {
        case AscSaveTypes.PartStart:
          this.downloadId = "_" + Math.round(Math.random() * 1000);
          this.downloadParts = [new Uint8Array(buffer)];
          break;
        case AscSaveTypes.Part:
          this.downloadParts.push(new Uint8Array(buffer));
          break;
        case AscSaveTypes.Complete:
          this.downloadParts.push(new Uint8Array(buffer));
          result = await download();
          this.downloadParts = [];
          this.finishSaveRequest(result.status === "ok");
          break;
        case AscSaveTypes.CompleteAll:
          this.downloadId = "_" + Math.round(Math.random() * 1000);
          this.downloadParts = [new Uint8Array(buffer)];
          result = await download();
          this.downloadParts = [];
          this.finishSaveRequest(result.status === "ok");
          break;
      }

      setTimeout(() => {
        send({
          type: "documentOpen",
          data: {
            type: "save",
            // status: "ok",
            status: result.status,
            data: "data:,",
            filetype: "pptx",
          },
        });
      }, 100);

      return Response.json({
        status: result.status,
        type: "save",
        data: this.downloadId,
      });
    }

    if (u.pathname.endsWith("/upload/" + key)) {
      const buffer = await req.arrayBuffer();
      const data = new Uint8Array(buffer);
      const filename = Date.now() + ".png";
      const pathname = "media/" + filename;
      const url = this.addMedia(filename, data);
      return Response.json({ [pathname]: url });
    }

    // 代理已将相对 URL 按 iframe base 解析为绝对路径（见 xhr/fetch），
    // 所以这里必须按后缀匹配，不能假定 pathname 恰为 /plugins.json。
    if (u.pathname.endsWith("/plugins.json")) {
      const state = this.options.getState?.();
      if (state?.plugins == "none") {
        return Response.json({ url: "", pluginsData: [], autostart: [] });
      }
      const names = state?.plugins == "all" ? allPlugins : featuredPlugins;
      // 本地 dev（非 VOS）：ziziyi 的远程 AI 插件与我们自己的「AI 助手」同名，
      // 其后端不在本地、点开必然空白，从列表去掉避免误点；VOS 模式保持原样。
      const localNames = (await isVOSMode())
        ? names
        : names.filter((name) => name !== "ai");
      const configs = localNames.map(getPluginConfigUrl);
      // 说明（2026-10）：编辑器内的「AI 助手」插件原来由 agentic-search 应用托管，
      // 已随该应用一起下线——本应用现在自带 AI 服务（server/ai.py + Pi），
      // 入口在「专利工作台 / AI 写作」两个栏目里，编辑器不再注入外部插件。
      // 好处是少一个跨应用软依赖：以前 agentic-search 没装或 config.json 404，
      // sdkjs 加载插件失败会把整个编辑器拖垮（「使用文档出错」）。
      return Response.json({ url: "", pluginsData: configs, autostart: [] });
    }

    return null;
  }
}

